import polars as pl


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    def parse_number(col_name: str) -> pl.Expr:
        return (
            pl.col(col_name)
            .str.replace_all(r"\.", "")
            .str.replace(r",", ".")
            .cast(pl.Float64, strict=False)
            .round(2)
        )

    return raw.select(
        account=pl.col("Acct"),
        txn_date=pl.col("Value Date").str.to_date("%d.%m.%Y", strict=False),
        description=pl.col("Narrative"),
        amount=parse_number("Amount"),
        balance=parse_number("Running Balance"),
        reference=pl.col("Transaction ID"),
    )
